function pill(s){const c=({OBSERVED:'mint',REFUTED_FOR_RUN:'red',POSSIBLE:'amber',UNKNOWN:'purple',SUCCESS:'mint',PASS:'mint',WARNING:'amber',FAILED:'red',FAIL:'red'})[s]||'gray';return '<span class="pill '+c+'">'+esc(s)+'</span>'}
function head(t,d,act=''){return '<div class="page-heading"><div><div class="eyebrow">KAIROS / WORKSPACE</div><h1>'+t+'</h1><p>'+d+'</p></div><div class="heading-actions">'+act+'</div></div>'}
function panel(t,body,sub='',act=''){return '<section class="panel"><div class="panel-head"><div><h2>'+t+'</h2>'+(sub?'<p>'+sub+'</p>':'')+'</div>'+act+'</div>'+body+'</section>'}
function table(h,rows,empty='No matching records'){return '<div class="table-wrap"><table><thead><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+h.length+'"><div class="empty-state"><strong>'+empty+'</strong>Try adjusting your filters.</div></td></tr>')+'</tbody></table></div>'}
