function walk(id,down=false,seen=new Set()){E.filter(e=>(down?e[0]===id:e[1]===id)).forEach(e=>{const n=down?e[1]:e[0];if(!seen.has(n)){seen.add(n);walk(n,down,seen)}});return [...seen]}
