function evidencePage(){const l=V.filter(e=>(S.evFilter==='all'||e.state===S.evFilter)&&(e.id+' '+e.source+' '+e.target+' '+e.rule).toLowerCase().includes(S.evSearch.toLowerCase())),ev=l.find(e=>e.id===S.selectedEv)||l[0]||V[0];return head('Evidence & reasoning','Inspect each lineage claim, its evidence, scope and limits.','<button class="btn" data-action="export-evidence">⇩ Export CSV</button>')+notice('Four-state semantics.','OBSERVED requires positive matching evidence. REFUTED_FOR_RUN requires a complete negative-evaluation contract for that run. POSSIBLE is not proof. UNKNOWN means insufficient evidence. Missing events alone do not prove absence.')+'<div class="stat-grid">'+card('Observed',V.filter(e=>e.state==='OBSERVED').length,'✓','Positive evidence examples')+card('Refuted for run',V.filter(e=>e.state==='REFUTED_FOR_RUN').length,'×','Run-scoped example')+card('Possible',V.filter(e=>e.state==='POSSIBLE').length,'?','Static / partial evidence')+card('Unknown',V.filter(e=>e.state==='UNKNOWN').length,'◇','Unresolved evaluation')+'</div><div class="toolbar"><label class="search-box"><span>⌕</span><input id="evSearch" value="'+esc(S.evSearch)+'" placeholder="Search source, target or rule…"></label><select id="evFilter"><option value="all">All states</option>'+['OBSERVED','REFUTED_FOR_RUN','POSSIBLE','UNKNOWN'].map(s=>'<option '+(S.evFilter===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div><div class="lineage-layout"><section class="panel">'+table(['ID','Source → target','State','Type','Run',''],l.map(e=>'<tr><td><strong>'+e.id+'</strong></td><td>'+esc(e.source)+'<div class="subline">↓ '+esc(e.target)+'</div></td><td>'+pill(e.state)+'</td><td>'+esc(e.type)+'</td><td class="mono">'+esc(e.run)+'</td><td><button class="btn small" data-action="select-evidence" data-id="'+e.id+'">Inspect</button></td></tr>'))+'</section><div class="side-stack">'+panel('Evidence detail','<div class="node-detail">'+pill(ev.state)+'<h3>'+esc(ev.source)+' → '+esc(ev.target)+'</h3><p>'+esc(ev.why)+'</p>'+[['Evidence type',ev.type],['Run identity',ev.run],['Coverage',ev.coverage],['Reasoning rule',ev.rule]].map(x=>'<div class="metric-line"><span>'+x[0]+'</span><strong>'+esc(x[1])+'</strong></div>').join('')+'<button class="btn small" data-action="copy-evidence" data-id="'+ev.id+'">Copy record JSON</button></div>')+panel('Reasoning guardrails','<div class="panel-body">'+['Never infer refutation from missing events alone.','Keep conclusions scoped to the evaluated run.','Keep static evidence separate from runtime observation.','Unresolved identity should remain explicit.'].map(x=>'<div class="activity-item"><div class="activity-icon blue">✓</div><div class="activity-copy"><p>'+x+'</p></div></div>').join('')+'</div>')+'</div></div>'}
