function qualityPage(){return head('Data quality','Review illustrative freshness, completeness, uniqueness and integrity checks.','<button class="btn" data-action="export-quality">⇩ Export CSV</button><button class="btn primary" data-action="run-quality">▶ Run demo checks</button>')+notice('Sample check results.','Scores are not computed against live sources. Running demo checks refreshes local sample statuses only.')+'<div class="stat-grid">'+card('Checks shown',Q.length,'◇','Sample rules')+card('Passing',Q.filter(q=>q.status==='PASS').length,'✓','Sample checks')+card('Warnings',Q.filter(q=>q.status==='WARNING').length,'!','Sample checks')+card('Average score',Math.round(Q.reduce((n,q)=>n+q.score,0)/Q.length)+'%','◎','Demo average')+'</div><div class="grid-2">'+panel('Quality rules',table(['Rule','Asset','Type','Score','Status'],Q.map(q=>'<tr><td><strong>'+q.name+'</strong></td><td>'+q.asset+'</td><td>'+q.type+'</td><td>'+q.score+'%</td><td>'+pill(q.status)+'</td></tr>')),'Illustrative rule results')+panel('Quality dimensions','<div class="panel-body"><div class="chart-wrap"><canvas id="qualityChart"></canvas></div></div>','Sample scores by rule')+'</div><div class="grid-equal section-spacer">'+panel('Suggested follow-up','<div class="panel-body"><p>Investigate feature freshness and attribution coverage using actual schedules, run history and defined expectations.</p></div>')+panel('Quality ≠ lineage proof','<div class="panel-body"><p class="small-note">A quality score describes a check under its own scope. It does not prove a lineage edge executed. Keep quality, static dependency and runtime evidence separate.</p></div>')+'</div>'}
